parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "appliedAt": {
      "type": "string",
      "description": "Application date and time, format YYYY-MM-DD HH:mm."
    },
    "name": { "type": "string", "description": "Candidate full name." },
    "email": { "type": "string", "description": "Candidate email address." },
    "position": { "type": "string", "description": "Job title the candidate applied for." },
    "motivation": { "type": "string", "description": "Motivation text if provided, otherwise an empty string." },
    "readMethod": { "type": "string", "description": "How the CV was read, e.g. 'PDF text' or 'OCR'." },
    "cvFileId": { "type": "string", "description": "Google Drive file ID of the CV." },
    "score": {
      "type": "integer",
      "minimum": 0,
      "maximum": 100,
      "description": "Overall fit score from 0 to 100 against the job requirements."
    },
    "recommendation": {
      "type": "string",
      "enum": ["interview", "maybe", "reject"],
      "description": "Hiring recommendation based on the score and requirements match."
    },
    "matched_requirements": {
      "type": "array",
      "items": { "type": "string" },
      "description": "Job requirements the CV satisfies, each with a short piece of evidence from the CV."
    },
    "missing_requirements": {
      "type": "array",
      "items": { "type": "string" },
      "description": "Job requirements not met or with no evidence in the CV, each with a short reason."
    },
    "strengths": {
      "type": "string",
      "description": "2-3 sentences summarizing the candidate's main strengths for this role."
    },
    "concerns": {
      "type": "string",
      "description": "2-3 sentences summarizing gaps or risks."
    },
    "interview_questions": {
      "type": "array",
      "items": { "type": "string" },
      "description": "3 tailored interview questions based on the candidate's CV and the gaps found."
    },
    "yearsExperience": {
      "type": "number",
      "description": "Total years of professional experience, including internships, rounded to 2 decimals."
    },
    "topSkills": {
      "type": "string",
      "description": "Comma-separated list of the candidate's most relevant skills for the role."
    },
    "valid": {
      "type": "boolean",
      "description": "true if the CV was readable and the evaluation is reliable, false otherwise."
    },
    "problems": {
      "type": "string",
      "description": "Description of any problem reading or evaluating the CV, or an empty string if none."
    }
  },
  "required": [
    "score",
    "recommendation",
    "matched_requirements",
    "missing_requirements",
    "strengths",
    "concerns",
    "interview_questions",
    "yearsExperience",
    "topSkills",
    "valid",
    "problems"
  ]
}

parameters.jsCode:
const ev = $input.first().json.output ?? $input.first().json;
const app = $('Prepare Application').first().json;
const profile = $('Extract Candidate Profile').first().json.output || {};
const cv = (app.cvText || '').toLowerCase();
const problems = [];

if (!Number.isInteger(ev.score) || ev.score < 0 || ev.score > 100) problems.push('score must be a whole number from 0 to 100');
if (!['interview', 'maybe', 'reject'].includes(ev.recommendation)) problems.push('recommendation must be interview, maybe or reject');
if (ev.recommendation === 'interview' && ev.score < 70) problems.push('interview needs a score of 70 or more');
if (ev.recommendation === 'reject' && ev.score >= 40) problems.push('reject needs a score below 40');
if (!(ev.matched_requirements || []).length && !(ev.missing_requirements || []).length) problems.push('the evaluation lists no requirements');

const unverified = (profile.skills || []).filter(s => !cv.includes(String(s).toLowerCase().split(' (')[0]));
if (unverified.length > 2) problems.push('skills not found in the CV: ' + unverified.join(', '));

const { cvText, jobRequirements, ...applicant } = app;
return [{ json: { ...applicant, ...ev, yearsExperience: $input.first().json.output.yearsExperience, topSkills: (profile.skills || []).slice(0, 6).join(', '),
  valid: problems.length === 0, problems: problems.join('; ') } }];

parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "years_of_experience": {
      "type": "number",
      "description": "Total years of professional work experience, including internships. Use 0 if none is stated."
    },
    "skills": {
      "type": "array",
      "description": "Technical and professional skills, tools and technologies mentioned in the CV.",
      "items": { "type": "string" }
    },
    "languages": {
      "type": "array",
      "description": "Spoken languages with proficiency level if stated, e.g. 'Arabic (Native)', 'English (B2)'.",
      "items": { "type": "string" }
    },
    "certifications": {
      "type": "array",
      "description": "Certifications, courses and training programs. Return an empty array if none are listed.",
      "items": { "type": "string" }
    },
    "education": {
      "type": "array",
      "description": "Education history, one entry per degree.",
      "items": {
        "type": "object",
        "properties": {
          "degree": {
            "type": "string",
            "description": "Degree and field of study, e.g. 'Bachelor of Computer Science'."
          },
          "institution": {
            "type": "string",
            "description": "University or school name."
          },
          "graduation_year": {
            "type": "string",
            "description": "Graduation year, or 'Expected YYYY' if still studying. Empty string if not stated."
          }
        },
        "required": ["degree", "institution"]
      }
    }
  },
  "required": ["years_of_experience", "skills", "languages", "certifications", "education"]
}
